import{_ as a,o,c as t,ae as i}from"./chunks/framework.1Lna8NcP.js";const u=JSON.parse('{"title":"ADR-006: Tier-1 Net Worth Dashboard Completion","description":"","frontmatter":{},"headers":[],"relativePath":"adr/006-tier1-dashboard-completion.md","filePath":"adr/006-tier1-dashboard-completion.md"}'),l={name:"adr/006-tier1-dashboard-completion.md"};function n(r,e,s,d,c,h){return o(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="adr-006-tier-1-net-worth-dashboard-completion" tabindex="-1">ADR-006: Tier-1 Net Worth Dashboard Completion <a class="header-anchor" href="#adr-006-tier-1-net-worth-dashboard-completion" aria-label="Permalink to &quot;ADR-006: Tier-1 Net Worth Dashboard Completion&quot;">​</a></h1><ul><li>Status: Accepted</li><li>Date: 2026-04-12</li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>Phase 2 required Libertas to ship a complete Tier-1 net worth experience: range-aware history, grouped account depth, deterministic offline insights, and measurable local performance.</p><p>Prior implementation gaps:</p><ul><li><code>/api/snapshots/net-worth</code> had no range controls.</li><li>Month-end continuity was not guaranteed.</li><li>Dashboard account scan and recommendation UX were incomplete.</li><li>Account details lacked search/filter depth and benchmark context.</li><li>Insights were rule-based but not aligned to a deterministic 15-rule model.</li></ul><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><ol><li>Introduce <code>backend/services/snapshots.py</code> as the canonical snapshot computation layer.</li><li>Extend snapshot API contract:</li></ol><ul><li><code>GET /api/snapshots/net-worth?range=1M|3M|6M|YTD|1Y|ALL</code></li><li><code>POST /api/snapshots/record-month-end</code></li><li><code>GET /api/snapshots/current</code> includes 30-day delta and timestamp metadata.</li></ul><ol start="3"><li>Keep insights fully local/offline and standardize to 15 deterministic rule cards.</li><li>Expand account depth:</li></ol><ul><li>transaction search/filter query params</li><li>holdings gain/loss and account-weight visibility</li><li>S&amp;P baseline comparison in account performance</li><li>real-estate account detail blocks (value, mortgage, LTV, equity)</li></ul><ol start="5"><li>Add a performance guardrail test (<code>test_dashboard_perf.py</code>) enforcing a sub-500ms snapshot path in local test conditions.</li></ol><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><p>Positive:</p><ul><li>Dashboard behavior now maps directly to Phase 2 functional requirements.</li><li>Core data path is tested across history, insights, account depth, and performance.</li><li>UI supports fast scanning and drill-in workflows without cloud dependencies.</li></ul><p>Trade-offs:</p><ul><li>S&amp;P comparison is a deterministic baseline approximation (8% annualized), not live index tracking.</li><li>Month-end backfill uses local snapshot continuity rather than new persistence models.</li></ul><h2 id="follow-ups" tabindex="-1">Follow-ups <a class="header-anchor" href="#follow-ups" aria-label="Permalink to &quot;Follow-ups&quot;">​</a></h2><ul><li>Phase 3 will layer onboarding and FIRE wizard workflows on top of this data model.</li><li>Phase 4 will replace single-provider chat assumptions with multi-model provider selection and prompt orchestration.</li></ul>',19)])])}const m=a(l,[["render",n]]);export{u as __pageData,m as default};
